def odd_even_list(values):
    odd = [values[i] for i in range(0, len(values), 2)]                    # collect values at 0-indexed EVEN positions (1st, 3rd, 5th...)
    even = [values[i] for i in range(1, len(values), 2)]                    # collect values at 0-indexed ODD positions (2nd, 4th, 6th...)
    return odd + even                                                       # rebuild: all odd-position nodes first, then all even-position nodes


if __name__ == "__main__":
    print(odd_even_list([1, 2, 3, 4, 5]))

