import java.util.*;

public class Main {
    List<Integer> oddEvenList(List<Integer> values) {
        List<Integer> odd = new ArrayList<>();
        List<Integer> even = new ArrayList<>();
        for (int i = 0; i < values.size(); i++) {
            if (i % 2 == 0) odd.add(values.get(i));                                 // 0-indexed EVEN positions are the 1st, 3rd, 5th... nodes
            else even.add(values.get(i));                                           // 0-indexed ODD positions are the 2nd, 4th, 6th... nodes
        }
        odd.addAll(even);                                                            // rebuild: all odd-position nodes first, then all even-position nodes
        return odd;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> values = Arrays.asList(1, 2, 3, 4, 5);
        System.out.println(solution.oddEvenList(values));
    }
}

