#include <bits/stdc++.h>
using namespace std;

vector<int> oddEvenList(vector<int>& values) {
    vector<int> odd, even;
    for (int i = 0; i < (int)values.size(); i++) {
        if (i % 2 == 0) odd.push_back(values[i]);                                  // 0-indexed EVEN positions are the 1st, 3rd, 5th... nodes
        else even.push_back(values[i]);                                            // 0-indexed ODD positions are the 2nd, 4th, 6th... nodes
    }
    odd.insert(odd.end(), even.begin(), even.end());                                 // rebuild: all odd-position nodes first, then all even-position nodes
    return odd;
}

int main() {
    vector<int> values = {1, 2, 3, 4, 5};
    vector<int> result = oddEvenList(values);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

