import java.util.*;

public class Main {
    ListNode oddEvenList(ListNode head) {
        if (head == null || head.next == null) return head;

        ListNode odd = head;                                                        // odd starts at the 1st node
        ListNode even = head.next;                                                    // even starts at the 2nd node
        ListNode evenHead = even;                                                      // remembered so it can be attached at the very end

        while (even != null && even.next != null) {
            odd.next = even.next;                                                        // skip odd past the in-between even node
            odd = odd.next;
            even.next = odd.next;                                                        // skip even past the in-between odd node
            even = even.next;
        }

        odd.next = evenHead;                                                            // attach the even chain right after the odd chain
        return head;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
        ListNode result = solution.oddEvenList(head);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

